    "production" "jsonb",
    "payments" "jsonb",
    "dispatch" "jsonb",
    "system" "jsonb",
    "financial" "jsonb",
    "orders" "jsonb"
);

-- DATA FOR stats

-- SCHEMA FOR staff_users
CREATE TABLE IF NOT EXISTS "public"."staff_users" (
    "id" "text" PRIMARY KEY NOT NULL,
